// Geometria real de Forest Hills, Queens (NYC) extraída do OpenStreetMap (ODbL)
// e embutida localmente para funcionamento 100% offline.

export const MAP_BOUNDS = {
  mx0: 0.2948388889,
  mx1: 0.2949138889,
  my0: 0.3759287544,
  my1: 0.3759947236,
  width: 2200.0,
  height: 1935.1,
} as const;

export function projectCoords(latitude: number, longitude: number): { x: number; y: number } {
  const mx = (longitude + 180) / 360;
  const rad = (latitude * Math.PI) / 180;
  const my = (1 - Math.log(Math.tan(rad) + 1 / Math.cos(rad)) / Math.PI) / 2;
  return {
    x: ((mx - MAP_BOUNDS.mx0) / (MAP_BOUNDS.mx1 - MAP_BOUNDS.mx0)) * MAP_BOUNDS.width,
    y: ((my - MAP_BOUNDS.my0) / (MAP_BOUNDS.my1 - MAP_BOUNDS.my0)) * MAP_BOUNDS.height,
  };
}

